// means "fact correct per a standard reference + topic within the
// cited HSC syllabus", NOT "confirmed against the book lesson". A
// teacher with the actual HSC books should spot-check chapter
// numbers before publication, especially the re-cited chapters
// (see review-academic-c11-12-fixes-applied.md).
//
// HONESTY: these are ORIGINAL practice questions written for the
// NCTB lessons — NOT board / university / previous-year questions.
// The draft files' `status` field still says NEEDS-REVIEW — the
// verdict files are the review record, and this file contains ONLY
// the usable questions. The 2 applied replacements (Bangla সুচেতনা,
// Islamic History Fatimid Caliphate) are new text and need a
// content-team spot-check before being treated as VERIFIED.
//
// HOW NEW BATCHES JOIN: regenerate with
// sprint-1week-2026-11-25/generate_academic_cq_pool.py (same shape,
// same draft + verdict files). Chapters, counts and the QPG picker
// are DERIVED from the combined pool in publicAcademicCq.ts, so no
// component or route change is needed when a batch is verified.
// NEVER add a question whose verdict is not VERIFIED (or NEEDS-FIX
// with the fix applied) — unverified drafts must never reach
// students. Class 12 shares the Class 11 questions (same combined
// class-11-12 draft set — there is NO separate Class 12 set).

