    "stimulus": "মৃত্যুঞ্জয় কায়স্থ ঘরের যুবক। অসুস্থ অবস্থায় সাপুড়ে-কন্যা বিলাসী তার সেবা করে তাকে সুস্থ করে তোলে। সমাজের জাতপাতের নিয়ম ভেঙে মৃত্যুঞ্জয় বিলাসীকে বিয়ে করে। তার খুড়ো ও গ্রামের লোকেরা এ বিয়ে মেনে নেয় না; তারা দুজনকে একঘরে করে দেয়, এমনকি বিলাসীর ওপর নির্যাতন চালায়। তবু বিলাসী স্বামীর সেবায় ও সংসারে নিজেকে উৎসর্গ করে।",
