    "unitNumber": 902,
    "topicId": "cq",
    "stimulus": "একটি দ্বিঘাত সমীকরণ x² − 5x + 6 = 0। একজন ছাত্র এর মূলদ্বয় বের করল। সে লক্ষ করল, মূলদ্বয়ের যোগফল ও গুণফল সমীকরণের সহগের সঙ্গে সম্পর্কিত।",
    "parts": [
      {
        "label": "ক",
        "marks": 1,
        "question": "দ্বিঘাত সমীকরণের সাধারণ রূপ লেখো।",
        "answer_outline": "ax² + bx + c = 0, যেখানে a ≠ 0।"
      },
      {
        "label": "খ",
        "marks": 2,
        "question": "মূলদ্বয় নির্ণয় করো।",
        "answer_outline": "x² − 5x + 6 = (x−2)(x−3) = 0 → x = 2, 3।"
      },
      {
        "label": "গ",
        "marks": 3,
        "question": "মূলদ্বয়ের যোগফল ও গুণফল নির্ণয় করো।",
        "answer_outline": "যোগফল = 2 + 3 = 5 = −b/a; গুণফল = 6 = c/a।"
      },
      {
        "label": "ঘ",
        "marks": 4,
        "question": "নিরূপক (b² − 4ac) মূলের প্রকৃতি নির্ধারণে কী ভূমিকা রাখে—বিশ্লেষণ করো।",
        "answer_outline": "নিরূপক ধনাত্মক হলে দুটি বাস্তব মূল, শূন্য হলে সমান মূল, ঋণাত্মক হলে জটিল মূল হয়—সমীকরণ সমাধানের আগেই মূলের প্রকৃতি জানা যায়।"
      }
    ],
